INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName", "factCheckVerdict", "factCheckClaim", "factCheckClaimant", "factCheckClaimUrl")
VALUES
(gen_random_uuid(), 'fact-check-europe-jobs-two-lakh-scam-20261122', 'fact-check', 'Nepal', 'Fact check: Europe for Rs 2 lakh is a scam, Nepal department warns', 'तथ्य जाँच: दुई लाखमा युरोप जान पाइन्छ भन्ने विज्ञापन ठगी हो', 'Viral ads promise Europe for Rs 2 lakh and pay up to Rs 10 lakh a month. The Nepal labour department calls such claims 100% fraud.', 'युरोप दुई लाखमा जान पाइन्छ र महिनामा १० लाख कमाइन्छ भन्ने भाइरल विज्ञापन झुटा हुन्। श्रम विभागले यस्ता दाबीलाई शतप्रतिशत ठगी भनेको छ।', $fc1$<p>Short videos on TikTok and Facebook promise Nepali jobseekers a shortcut to Europe for Rs 2 lakh, with salaries of up to Rs 10 lakh a month once they arrive. The claim is false. Nepal's Department of Foreign Employment says advertisements like these are 100% fraud, and it has over 28,000 fraud complaints on file. This <a href="https://growentix.cloud/stories">Fact Check</a> traces what the ads promise, what victims actually pay, and how to verify any foreign job offer before paying anyone.</p><table><tbody><tr><td>Claim</td><td>Go to Europe for just Rs 2 lakh and earn up to Rs 10 lakh a month</td></tr><tr><td>Verdict</td><td>False</td></tr><tr><td>Claimed by</td><td>Viral TikTok and Facebook ads</td></tr><tr><td>Checked by</td><td>Growentix, 22 November 2026</td></tr></tbody></table><h2>What we found on the Europe for Rs 2 lakh claim</h2><p>The advertisements offer very cheap packages to Europe: pay only Rs 2 lakh now, the ads say, and pay the rest after reaching Europe and starting work. The Department of Foreign Employment says the opposite is what happens. Once people trust the ads and hand over passports and advance payments, the agents demand more money for medical reports, police reports, visa processing and documentation, and victims end up paying Rs 6 lakh to Rs 10 lakh for tickets and processing. When the money is paid, the agents block the victims on Facebook, Viber and WhatsApp and disappear.</p><h2>What the evidence shows about Europe for Rs 2 lakh</h2><p>The department's own words settle the claim. It told <a href="http://english.ratopati.com/story/85584/attractive-ads-on-tiktok-and-facebook-millions-of-people-cheated-by-claiming-to-fly-to-europe-cheaply">Ratopati</a> that claims of sending people to Europe without skills and at a low price are 100% fraud, and that advertising foreign employment on social media with misleading information is illegal. Director General Nawaraj Dhakal said the department is working with the Cyber Bureau of Nepal Police to identify and shut down the pages and accounts posting these advertisements. The scale is in the department's own figures: a pile of over 28,000 fraud complaints, and four people arrested in a single week — Ashika Simkhada, who took Rs 7.5 lakh promising the UK; Bishnu Khatri, Rs 6 lakh for Malta; Dinesh Pakhren Tamang, Rs 2 lakh for the UAE; and Rajesh Baram, Rs 15.5 lakh for Singapore. Confidence: 95%. The verdict rests on a direct statement from the authority that regulates foreign employment, backed by complaint volumes and arrests; the remaining 5% reflects that individual agents and ad accounts change names faster than they can be listed. Never pay anyone for a job before verifying the offer: check whether the agency holds a government permit and whether the demand letter is genuine on the department's website or app before proceeding.</p><h2>What is still unclear</h2><p>We cannot list every account running these ads — new pages appear daily, and the department says the number of complaints fluctuates as cases are resolved. The exact number of people defrauded by the Rs 2 lakh promise alone is not published separately from the overall complaint pile. What is clear is the pattern: a small upfront figure, then repeated demands until the victim has paid several lakhs and the agent vanishes.</p><p>Sources: <a href="http://english.ratopati.com/story/85584/attractive-ads-on-tiktok-and-facebook-millions-of-people-cheated-by-claiming-to-fly-to-europe-cheaply">Ratopati</a>, report on the social media ads, the four arrests and the department's warning; <a href="https://dofe.gov.np/">Department of Foreign Employment</a>, the official portal where permits and demand letters can be verified.</p><h2>Frequently asked questions</h2><h3>How can I check if a foreign job offer is real?</h3><p>Check whether the agency holds a government permit and whether the demand letter is genuine on the Department of Foreign Employment website or app before paying anything or handing over your passport.</p><h3>I already paid an agent who promised Europe for Rs 2 lakh — what do I do?</h3><p>Keep every receipt, message and screenshot, and file a complaint with the Department of Foreign Employment and the Cyber Bureau of Nepal Police. Do not pay more money to the same agent.</p>$fc1$, $fc1$<p>टिकटक र फेसबुकमा युरोप दुई लाख रुपैयाँमा जान पाइन्छ र महिनामा १० लाखसम्म कमाइन्छ भन्ने विज्ञापन फैलिएका छन्। यो दाबी झुटा हो। वैदेशिक रोजगार विभागले यस्ता विज्ञापन शतप्रतिशत ठगी भएको बताएको छ र विभागमा २८ हजारभन्दा बढी ठगीसम्बन्धी उजुरी छन्। पीडितहरूले सुरुमा दुई लाख तिरेपछि एजेन्टहरूले मेडिकल, प्रहरी प्रतिवेदन, भिसा प्रक्रिया र टिकटका नाममा ६ देखि १० लाख रुपैयाँसम्म असुल्छन्, त्यसपछि सम्पर्कविच्छेद गर्छन्। विदेश जानुअघि एजेन्सीको अनुमति र मागपत्र विभागको वेबसाइट वा एपबाट जाँच गर्नुपर्छ।</p>$fc1$, ARRAY['http://english.ratopati.com/story/85584/attractive-ads-on-tiktok-and-facebook-millions-of-people-cheated-by-claiming-to-fly-to-europe-cheaply', 'https://dofe.gov.np/'], NOW(), NOW(), NOW(), NOW(), NULL, 'FALSE', 'Go to Europe for just Rs 2 lakh and earn up to Rs 10 lakh a month.', 'Viral TikTok and Facebook ads', NULL) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName", "factCheckVerdict", "factCheckClaim", "factCheckClaimant", "factCheckClaimUrl")
VALUES
(gen_random_uuid(), 'fact-check-fbi-houston-20000-ballots-20261122', 'fact-check', 'USA', 'Fact check: No, the FBI did not find 20,000 fake ballots in Houston', 'तथ्य जाँच: एफबीआईले ह्युस्टनमा २० हजार नक्कली मतपत्र फेला पारेको होइन', 'A viral Election Day post claims an FBI raid in Houston found 20,000 fraudulent ballots for Democrats. The FBI says no such operation happened.', 'ह्युस्टनमा एफबीआई छापामा डेमोक्र्याटका लागि २० हजार नक्कली मतपत्र भेटिएको भन्ने भाइरल पोस्ट झुटा हो। एफबीआईले त्यस्तो कुनै कारबाही नभएको बताएको छ।', $fc2$<p>A post shared on Election Day, 3 November 2026, claimed an FBI raid of a Houston storage warehouse had uncovered over 20,000 fraudulent ballots, all marked for Democratic candidates. The claim is false. The FBI says no such operation took place, the county office that runs Houston elections says the story is false, and the photos attached to the post come from other places and events. This <a href="https://growentix.cloud/stories">Fact Check</a> traces the claim to its source and the evidence that contradicts it.</p><table><tbody><tr><td>Claim</td><td>An FBI raid in Houston found over 20,000 fraudulent ballots for Democrats</td></tr><tr><td>Verdict</td><td>False</td></tr><tr><td>Claimed by</td><td>X account @TrumpNews_Baby, 3 November 2026</td></tr><tr><td>Checked by</td><td>Growentix, 22 November 2026</td></tr></tbody></table><h2>What we found on the FBI Houston ballots claim</h2><p>The post went up at 6:45 a.m. Central Time on Election Day, with an all-caps headline about twenty thousand fraudulent ballots uncovered in an FBI raid of a Houston storage locker warehouse. It spread quickly across X, Facebook and Threads. Nothing in it checks out: the agency named denies the raid, the election office in charge denies the ballots, and the images do not show a Houston raid at all.</p><h2>What the evidence shows about the Houston ballots</h2><p>The FBI gave the same statement to several outlets on 3 November. As published by <a href="https://thewholeread.com/plumb-line/claims/houston-fbi-raid-20000-fraudulent-ballots-claim/">The Whole Read</a>, it reads: FBI Houston is aware of social media posts claiming the office conducted an election-related raid that uncovered fraudulent ballots on 2 November 2026. That information is false and no election-related operation occurred. The same wording was given to AFP by Connor Hagan, public affairs officer for FBI Houston. Harris County, which runs elections in Houston, agrees: County Clerk Teneshia Hudspeth told <a href="https://www.facebook.com/politifact/posts/pfbid0raVZqJUh61pniC4ynwa6rUPhTzyyUK3E8QJAquUUX6PDitEv6bR9ipeJbDiU5Pazl">PolitiFact</a> the information circulating on social media is false. The photos were traced independently by three outlets: one shows an FBI vehicle from the January 2026 search of the Fulton County election hub in Union City, Georgia; the others show San Francisco mail ballots and a generic storage facility. CNN reported the same FBI denial after speaking to a Houston spokesperson, as documented in the <a href="https://www.threads.com/@doniecnn/post/DfTJeikDRaC">Threads post by Donie O'Sullivan</a>. Confidence: 98%. The verdict rests on a direct denial from the agency named in the claim, confirmed by the county election office, plus the photo provenance. See also our check of the <a href="https://growentix.cloud/articles/fact-check-trump-redcoat-white-house-20261122">Trump redcoat image</a>, another viral post that mixed a real event with fabricated detail.</p><h2>What is still unclear</h2><p>Snopes found the account behind the post lists itself as a comedian on Facebook, so the post may have started as a joke — but we rate the claim as it spread, not the poster's intent. The exact origin of the storage-facility photo is not pinned down, only that it is not a Houston raid.</p><p>Sources: <a href="https://thewholeread.com/plumb-line/claims/houston-fbi-raid-20000-fraudulent-ballots-claim/">The Whole Read</a>, full check of the claim with the FBI statement and photo tracing; <a href="https://www.facebook.com/politifact/posts/pfbid0raVZqJUh61pniC4ynwa6rUPhTzyyUK3E8QJAquUUX6PDitEv6bR9ipeJbDiU5Pazl">PolitiFact</a>, the Harris County Clerk denial and photo debunk; <a href="https://www.threads.com/@doniecnn/post/DfTJeikDRaC">Donie O'Sullivan / CNN</a>, the FBI Houston denial reported the same day.</p><h2>Frequently asked questions</h2><h3>Did the FBI raid anything in Houston on 2 November 2026?</h3><p>No. FBI Houston said it is aware of the social media posts, that the information is false, and that no election-related operation occurred.</p><h3>Where did the photos in the post come from?</h3><p>One shows an FBI vehicle from a January 2026 search in Fulton County, Georgia. The others show San Francisco mail ballots and a generic storage facility — none shows a Houston raid.</p>$fc2$, $fc2$<p>३ नोभेम्बर २०२६ मा चुनावको दिन फैलिएको पोस्टले ह्युस्टनमा एफबीआई छापामा डेमोक्र्याटका लागि २० हजार नक्कली मतपत्र भेटिएको दाबी गर्‍यो। यो झुटा हो। एफबीआईले त्यस्तो कुनै कारबाही नभएको बताएको छ, ह्युस्टनको निर्वाचन हेर्ने ह्यारिस काउन्टीले पनि कथा झुटा भएको बताएको छ, र पोस्टका तस्बिरहरू अन्य ठाउँ र घटनाका हुन्। एउटा तस्बिर सन् २०२६ जनवरीमा जर्जियामा भएको खोजीको हो।</p>$fc2$, ARRAY['https://thewholeread.com/plumb-line/claims/houston-fbi-raid-20000-fraudulent-ballots-claim/', 'https://www.facebook.com/politifact/posts/pfbid0raVZqJUh61pniC4ynwa6rUPhTzyyUK3E8QJAquUUX6PDitEv6bR9ipeJbDiU5Pazl', 'https://www.threads.com/@doniecnn/post/DfTJeikDRaC'], NOW(), NOW(), NOW(), NOW(), NULL, 'FALSE', 'An FBI raid of a Houston storage warehouse uncovered over 20,000 fraudulent ballots, all for Democrats.', 'X account @TrumpNews_Baby, 3 November 2026', NULL) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName", "factCheckVerdict", "factCheckClaim", "factCheckClaimant", "factCheckClaimUrl")
VALUES
(gen_random_uuid(), 'fact-check-niagara-falls-blue-democrats-20261122', 'fact-check', 'Canada', 'Fact check: Niagara Falls was not lit blue for the Democrats', 'तथ्य जाँच: नियाग्रा फल्स डेमोक्र्याटका लागि नीलो बालिएको होइन', 'A viral photo claims Canada lit Niagara Falls blue for the Democrats. The falls were lit teal for Alzheimer Awareness Month, the operator says.', 'क्यानडाले डेमोक्र्याटका लागि नियाग्रा फल्स नीलो बालेको भन्ने भाइरल तस्बिर झुटा हो। फल्स अल्जाइमर सचेतना महिनाका लागि टिल रङमा बालिएको थियो।', $fc3$<p>A night-time photograph of Niagara Falls lit in deep blue spread across X, Facebook and Threads with the claim that Canada had lit the falls blue in solidarity with the Democrats. The claim is false. The falls were indeed lit that night — in teal, for Alzheimer's Awareness Month — and the body that runs the lights says partisan political displays are not permitted. This <a href="https://growentix.cloud/stories">Fact Check</a> explains what was actually lit, and when.</p><table><tbody><tr><td>Claim</td><td>Canada lit Niagara Falls blue in solidarity with Democrats</td></tr><tr><td>Verdict</td><td>False</td></tr><tr><td>Claimed by</td><td>Viral posts on X, Facebook and Threads</td></tr><tr><td>Checked by</td><td>Growentix, 22 November 2026</td></tr></tbody></table><h2>What we found on the Niagara Falls blue claim</h2><p>The photograph is real, and the falls were lit on the night the Democrats' midterm wins were being celebrated online. What is false is the reason. The colour in the photo is close to blue, and the post offers no date for the photo, no official source for the lighting and no indication of where the image came from. The claim fills that gap with a political motive that the operator denies.</p><h2>What the evidence shows about Niagara Falls blue</h2><p>Katy Wassenaar, a Niagara Parks spokesperson, told both AFP and Lead Stories that every illumination is administered by the Niagara Falls Illumination Board and that partisan political displays are not permitted under the board's policies and guidelines. The same statements describe the display that ran on the night of 3 November 2026 as a teal illumination for Alzheimer's Awareness Month, with an illumination schedule putting that teal lighting at 10:00 to 10:15 pm local time. Three independent fact-checking outlets reached the same conclusion on 4 November 2026, as documented by <a href="https://whatthefact.app/fact-checks/2026-11-05-niagara-falls-lit-blue-for-democrats-midterm-win">What The Fact</a>. Confidence: 95%. The verdict rests on a direct statement from the body that runs the lights, plus the published illumination schedule; the remaining 5% reflects that the exact time the shared photograph was taken is not recorded, so we cannot say with certainty which night's lighting it captures. See also our check of the <a href="https://growentix.cloud/articles/fact-check-fbi-houston-20000-ballots-20261122">FBI Houston ballots claim</a>, where the photos were also real but from other events.</p><h2>What is still unclear</h2><p>The shared photograph was first posted on Threads by a user who said they took it themselves, but the input does not record the exact time it was taken. That does not change the verdict: whatever night it shows, a partisan blue display for the Democrats was never booked, because the board does not permit one.</p><p>Sources: <a href="https://whatthefact.app/fact-checks/2026-11-05-niagara-falls-lit-blue-for-democrats-midterm-win">What The Fact</a>, full check citing the Niagara Parks statements, the illumination schedule and the three outlets that reached the same conclusion; AFP Fact Check and Lead Stories, which obtained the statements from the Niagara Parks spokesperson.</p><h2>Frequently asked questions</h2><h3>What colour were the falls on 3 November 2026?</h3><p>Teal, for Alzheimer's Awareness Month, from 10:00 to 10:15 pm local time — not blue for a political party.</p><h3>Who decides the colours at Niagara Falls?</h3><p>The Niagara Falls Illumination Board administers every illumination, and its policies do not permit partisan political displays.</p>$fc3$, $fc3$<p>नियाग्रा फल्स नीलो रङमा बालेको तस्बिर डेमोक्र्याटप्रति ऐक्यबद्धता देखाउन क्यानडाले बालेको भन्ने दाबीसहित फैलियो। यो झुटा हो। ३ नोभेम्बर २०२६ को राति फल्स टिल रङमा बालिएको थियो, अल्जाइमर सचेतना महिनाका लागि। बत्ती सञ्चालन गर्ने नियाग्रा पार्क्सले राजनीतिक प्रदर्शनका लागि बत्ती बाल्न नपाइने बताएको छ।</p>$fc3$, ARRAY['https://whatthefact.app/fact-checks/2026-11-05-niagara-falls-lit-blue-for-democrats-midterm-win'], NOW(), NOW(), NOW(), NOW(), NULL, 'FALSE', 'Canada just lit up Niagara Falls blue showing their solidarity with Democrats.', 'Viral posts on X, Facebook and Threads', NULL) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName", "factCheckVerdict", "factCheckClaim", "factCheckClaimant", "factCheckClaimUrl")
VALUES
(gen_random_uuid(), 'fact-check-trump-redcoat-white-house-20261122', 'fact-check', 'USA', 'Fact check: Trump redcoat image is AI-made, the post is real', 'तथ्य जाँच: ट्रम्पको रेडकोट तस्बिर एआईबाट बनेको हो, पोस्ट भने वास्तविक हो', 'A viral screenshot shows Trump in a British redcoat under Patriots in Control. The White House post is real, but the redcoat is AI-generated.', 'प्याट्रियट्स इन कन्ट्रोल लेखिएको पोस्टमा ट्रम्प ब्रिटिस रेडकोटमा देखिएको तस्बिर भाइरल भयो। पोस्ट वास्तविक हो, तर रेडकोट एआईबाट बनाइएको हो।', $fc4$<p>A screenshot that looks like a White House social media post shows Donald Trump in an 18th-century British redcoat uniform, under the words Patriots in Control and the caption No Panicans. Patriots are still in control btw. The claim is misleading: the White House post is real, but the redcoat is not. In the genuine post Trump wears a shirt, tie and dark overcoat — the redcoat figure was spliced in with AI. This <a href="https://growentix.cloud/stories">Fact Check</a> separates what the White House actually posted from what was added.</p><table><tbody><tr><td>Claim</td><td>The White House posted Trump in a British redcoat with Patriots in Control</td></tr><tr><td>Verdict</td><td>Misleading</td></tr><tr><td>Claimed by</td><td>X account @JesusChryslerII, 18 November 2026</td></tr><tr><td>Checked by</td><td>Growentix, 22 November 2026</td></tr></tbody></table><h2>What we found on the Trump redcoat image</h2><p>Two things are true and one is not. The White House did publish the exact caption and the Patriots in Control overlay on 10 November 2026, across several platforms. In that genuine post, Trump wears a shirt, tie and dark overcoat. The redcoat is an addition: an AI-generated figure spliced into a copy of the real post, so the frame, the account and the text all look official. The screenshot was posted on X on 18 November 2026 and quickly reposted across X, Bluesky, Facebook, Instagram and Threads.</p><h2>What the evidence shows about the Trump redcoat image</h2><p>AFP Fact Check, Lead Stories and MEAWW each checked the administration's live and archived accounts and found the overcoat version, never a redcoat one. If the White House had posted a redcoat image, the original would still be live or archived. Detection tools reached the same conclusion from the other direction: UncovAI's verification tool rated the redcoat image AI-generated with full confidence, and Hive, UncovAI, Pangram and veraAI agreed. The two lines of evidence are independent in method — one checks the official record, the other checks the pixels — and both point the same way, as documented by <a href="https://whatthefact.app/fact-checks/2026-11-20-white-house-posted-trump-as-british-redcoat-patriots-in-control">What The Fact</a>. Confidence: 95%. The verdict is misleading rather than false because the post, the caption and the overlay are genuine; only the uniform was fabricated. See also our check of the <a href="https://growentix.cloud/articles/fact-check-trump-troops-kneeling-ai-video-20261122">Trump troops kneeling video</a>, where the AI content was real and the posting was real too.</p><h2>What is still unclear</h2><p>We did not identify who created the edited screenshot or which tool produced the redcoat figure. The account that spread it is a repeat origin point for viral misinformation — Lead Stories had already debunked its 31 October 2026 Elon Musk helicopter video — but that history is context, not proof of who made this image.</p><p>Sources: <a href="https://whatthefact.app/fact-checks/2026-11-20-white-house-posted-trump-as-british-redcoat-patriots-in-control">What The Fact</a>, full check of the claim with the account comparison and the AI-detection results; AFP Fact Check, Lead Stories and MEAWW, which checked the official White House accounts.</p><h2>Frequently asked questions</h2><h3>Did the White House really post Patriots in Control?</h3><p>Yes. The White House published that caption and overlay on 10 November 2026. What it did not post is the redcoat version of the image.</p><h3>How do we know the redcoat is AI-made?</h3><p>Two ways: no redcoat version exists on the White House live or archived accounts, and AI-detection tools including UncovAI, Hive, Pangram and veraAI rated the redcoat figure AI-generated.</p>$fc4$, $fc4$<p>ह्वाइट हाउसको जस्तो देखिने स्क्रिनसटमा डोनाल्ड ट्रम्प १८औँ शताब्दीको ब्रिटिस रेडकोटमा प्याट्रियट्स इन कन्ट्रोल लेखिएसहित देखिए। यो दाबी भ्रामक छ: पोस्ट वास्तविक हो, तर रेडकोट होइन। वास्तविक पोस्टमा ट्रम्प सर्ट, टाई र गाढा ओभरकोटमा छन् — रेडकोट एआईबाट थपिएको हो। एएफपी, लिड स्टोरीज र एमईएडब्लुले आधिकारिक खातामा रेडकोट संस्करण कहिल्यै भेटेनन्, र एआई पत्ता लगाउने उपकरणहरूले तस्बिर एआईबाट बनेको ठहर गरे।</p>$fc4$, ARRAY['https://whatthefact.app/fact-checks/2026-11-20-white-house-posted-trump-as-british-redcoat-patriots-in-control'], NOW(), NOW(), NOW(), NOW(), NULL, 'MISLEADING', 'The White House posted an image of Donald Trump in a British redcoat with the words Patriots in Control.', 'X account @JesusChryslerII, 18 November 2026', NULL) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt", "verifiedAt", "authorName", "factCheckVerdict", "factCheckClaim", "factCheckClaimant", "factCheckClaimUrl")
VALUES
(gen_random_uuid(), 'fact-check-trump-troops-kneeling-ai-video-20261122', 'fact-check', 'USA', 'Fact check: Yes, Trump posted an AI video of troops kneeling', 'तथ्य जाँच: हो, ट्रम्पले घुँडा टेकेका सैनिकको एआई भिडियो पोस्ट गरेका हुन्', 'A video of troops kneeling before planes is 91.8% AI-generated, and Donald Trump did post it on Truth Social on 15 November 2026. The claim is true.', 'विमानअगाडि घुँडा टेकेका सैनिकको भिडियो ९१.८% एआईबाट बनेको हो, र डोनाल्ड ट्रम्पले यसलाई १५ नोभेम्बर २०२६ मा ट्रुथ सोसलमा पोस्ट गरेकै हुन्। दाबी सत्य हो।', $fc5$<p>A video showing troops kneeling and praying in front of planes spread online with the claim that President Donald Trump posted it — and that the video itself is AI-generated. The claim is true on both counts. Trump did post the video on Truth Social, without an AI disclaimer, and detection tools found it 91.8% AI-generated. This <a href="https://growentix.cloud/stories">Fact Check</a> verifies the post and the video separately, because each half of the claim needs its own evidence.</p><table><tbody><tr><td>Claim</td><td>Trump posted an AI-generated video of troops kneeling and praying in front of planes</td></tr><tr><td>Verdict</td><td>True</td></tr><tr><td>Claimed by</td><td>Viral posts on X and Facebook sharing the clip</td></tr><tr><td>Checked by</td><td>Growentix, 22 November 2026</td></tr></tbody></table><h2>What we found on the Trump troops kneeling video</h2><p>The post is documented, not rumoured. A screenshot of Trump's Truth Social account (@realDonaldTrump) dated 15 November 2026 at 6:58 PM shows the video of soldiers kneeling on a tarmac, posted without any AI disclaimer. The video itself is not new footage: <a href="https://leadstories.com/3568ac">Lead Stories</a> first determined it was AI-generated in April 2026, when it first appeared, and confirmed the finding again after the November post.</p><h2>What the evidence shows about the Trump troops kneeling video</h2><p>Two checks, both positive. First, the posting: the Truth Social screenshot carries the account, the date and the time, and the video is visible in the post. Second, the content: an AI detection interface powered by Hive indicated the video was 91.8% AI-generated. Lead Stories' November video walks through both, and its report is linked as the source below, alongside the <a href="https://www.facebook.com/reel/1691833969220514/">Lead Stories video on Facebook</a>. Confidence: 95%. The post is documented with a timestamped screenshot and the AI finding comes from detection tools; the remaining 5% reflects that the video's original April 2026 context is reported second-hand rather than from the original post. Contrast this with our check of the <a href="https://growentix.cloud/articles/fact-check-trump-redcoat-white-house-20261122">Trump redcoat image</a>, where the post was real but the image was fabricated.</p><h2>What is still unclear</h2><p>We cannot say from the available evidence why the video was posted without an AI disclaimer, or whether the account that posted it knew it was AI-generated. The verdict covers only what the claim asserts: that Trump posted it, and that it is AI-generated. Both are true.</p><p>Sources: <a href="https://leadstories.com/3568ac">Lead Stories</a>, the report confirming the Truth Social post of 15 November 2026 and the April 2026 AI determination; <a href="https://www.facebook.com/reel/1691833969220514/">Lead Stories on Facebook</a>, the video showing the post screenshot and the Hive detection result of 91.8% AI-generated.</p><h2>Frequently asked questions</h2><h3>When did the video first appear?</h3><p>Lead Stories first determined it was AI-generated in April 2026, when the video first appeared. The Truth Social post in question is dated 15 November 2026.</p><h3>Did Trump label the video as AI?</h3><p>No. The Truth Social post of 15 November 2026 carried no AI disclaimer.</p>$fc5$, $fc5$<p>विमानअगाडि घुँडा टेकेर प्रार्थना गरिरहेका सैनिकको भिडियो डोनाल्ड ट्रम्पले पोस्ट गरेको र भिडियो एआईबाट बनेको भन्ने दाबी सत्य हो। १५ नोभेम्बर २०२६ मा ट्रुथ सोसलमा @realDonaldTrump खाताबाट भिडियो पोस्ट भएको स्क्रिनसटले देखाउँछ, र हाइभ पत्ता लगाउने उपकरणले भिडियो ९१.८% एआईबाट बनेको ठहर गरेको छ। लिड स्टोरीजले यो भिडियो पहिलो पटक अप्रिल २०२६ मा एआईबाट बनेको ठहर गरेको थियो।</p>$fc5$, ARRAY['https://leadstories.com/3568ac', 'https://www.facebook.com/reel/1691833969220514/'], NOW(), NOW(), NOW(), NOW(), NULL, 'TRUE', 'President Donald Trump posted an AI-generated video of troops kneeling and praying in front of planes.', 'Viral posts on X and Facebook sharing the clip', 'https://leadstories.com/3568ac') ON CONFLICT ("slug") DO NOTHING;
